def fib(limit):
    a, b = 0, 1
    while a < limit:
        yield a
        a, b = b, a + b
        if a > limit:
            break
    return 'done'

def primes(n):
    result = []
    for num in range(2, n + 1):
        is_prime = True
        for i in range(2, num):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            result.append(num)
    return result

# Usage: primes(10) returns [2, 3, 5, 7]

